css:
.formula {
            font-family: 'Courier New', monospace;
            background: #f3f4f6;
            padding: 0.5rem;
            border-radius: 0.25rem;
            overflow-x: auto;
        }

.content-section {
                display: none;
                opacity: 0;
                transition: opacity 0.3s ease-in-out;
            }
            .content-section.active {
                display: block;
                opacity: 1;
            }

.nav-link {
            position: relative;
            transition: all 0.3s ease;
        }

        .nav-link.active {
            background-color: var(--active-bg, rgb(243, 244, 246));
        }

        .nav-link.active[data-section="basic-principles"] {
            --active-bg: rgb(239, 246, 255);
            color: rgb(37, 99, 235);
        }

        .nav-link.active[data-section="simulations"] {
            --active-bg: rgb(238, 242, 255);
            color: rgb(79, 70, 229);
        }

        .nav-link.active[data-section="electrode-processes"] {
            --active-bg: rgb(245, 243, 255);
            color: rgb(124, 58, 237);
        }

        .nav-link.active[data-section="industrial-applications"] {
            --active-bg: rgb(249, 250, 251);
            color: rgb(31, 41, 55);
        }

        .nav-link.active[data-section="practice-questions"] {
            --active-bg: rgb(253, 242, 248);
            color: rgb(219, 39, 119);
        }

        .nav-link.active[data-section="calculations"] {
            --active-bg: rgb(240, 253, 244);
            color: rgb(22, 163, 74);
        }

        .nav-link.active[data-section="exam-tips"] {
            --active-bg: rgb(254, 252, 232);
            color: rgb(202, 138, 4);
        }

        .content-section {
            transition: opacity 0.3s ease-in-out;
            max-width: 100%;
            margin: 0 auto;
        }

        .content-section.hidden {
            display: none;
            opacity: 0;
        }

        .content-section:not(.hidden) {
            display: block;
            opacity: 1;
        }

        .main-content {
            max-width: 100%;
            width: 100%;
            overflow-x: hidden;
        }

        @media (min-width: 768px) {
            .content-section {
                max-width: 800px;
            }
        }

        .formula {
            max-width: 100%;
            overflow-x: auto;
        }
